","<EVENT_INSTANCE><EventType>CREATE_VIEW</EventType><PostTime>2023-05-08T12:07:39.563</PostTime><SPID>61</SPID><ServerName>SQL150</ServerName><LoginName>WEST\randolph</LoginName><UserName>dbo</UserName><DatabaseName>AdventureWorks2019</DatabaseName><SchemaName>Sales</SchemaName><ObjectName>vSalesPersonSalesByFiscalYears</ObjectName><ObjectType>VIEW</ObjectType><TSQLCommand><SetOptions ANSI_NULLS=""ON"" ANSI_NULL_DEFAULT=""ON"" ANSI_PADDING=""ON"" QUOTED_IDENTIFIER=""ON"" ENCRYPTED=""FALSE""/><CommandText>&#x0D;
CREATE VIEW [Sales].[vSalesPersonSalesByFiscalYears] &#x0D;
AS &#x0D;
SELECT &#x0D;
    pvt.[SalesPersonID]&#x0D;
    ,pvt.[FullName]&#x0D;
    ,pvt.[JobTitle]&#x0D;
    ,pvt.[SalesTerritory]&#x0D;
    ,pvt.[2002]&#x0D;
    ,pvt.[2003]&#x0D;
    ,pvt.[2004] &#x0D;
FROM (SELECT &#x0D;
        soh.[SalesPersonID]&#x0D;
        ,p.[FirstName] + ' ' + COALESCE(p.[MiddleName], '') + ' ' + p.[LastName] AS [FullName]&#x0D;
        ,e.[JobTitle]&#x0D;
        ,st.[Name] AS [SalesTerritory]&#x0D;
        ,soh.[SubTotal]&#x0D;
        ,YEAR(DATEADD(m, 6, soh.[OrderDate])) AS [FiscalYear] &#x0D;
    FROM [Sales].[SalesPerson] sp &#x0D;
        INNER JOIN [Sales].[SalesOrderHeader] soh &#x0D;
        ON sp.[BusinessEntityID] = soh.[SalesPersonID]&#x0D;
        INNER JOIN [Sales].[SalesTerritory] st &#x0D;
        ON sp.[TerritoryID] = st.[TerritoryID] &#x0D;
        INNER JOIN [HumanResources].[Employee] e &#x0D;
        ON soh.[SalesPersonID] = e.[BusinessEntityID] &#x0D;
		INNER JOIN [Person].[Person] p&#x0D;
		ON p.[BusinessEntityID] = sp.[BusinessEntityID]&#x0D;
	 ) AS soh &#x0D;
PIVOT &#x0D;
(&#x0D;
    SUM([SubTotal]) &#x0D;
    FOR [FiscalYear] &#x0D;
    IN ([2002], [2003], [2004])&#x0D;
) AS pvt;&#x0D;
</CommandText></TSQLCommand></EVENT_INSTANCE>"
